import json

@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    nums = draw(st.lists(st.integers(0, 15), min_size=n, max_size=n))
    k = draw(st.integers(0, 15))
    return f"{json.dumps(nums)}\n{k}"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) != 2:
        return False
    try:
        nums = json.loads(lines[0])
        k = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(nums, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    if not (1 <= len(nums) <= 10**5):
        return False
    if not all(isinstance(v, int) and not isinstance(v, bool) and 0 <= v <= 10**6 for v in nums):
        return False
    if not (0 <= k <= 10**6):
        return False
    return True

def ref(inp):
    # Derivation: let x = XOR of all nums and d = x ^ k.
    # One operation flips a single bit of one element, which flips exactly one
    # bit of the total XOR. So at least popcount(d) operations are needed, and
    # flipping each set bit of d once (on any element) achieves exactly k.
    lines = inp.split("\n")
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    x = 0
    for v in nums:
        x ^= v
    d = x ^ k
    return json.dumps(bin(d).count("1"))
