from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    nums = draw(st.lists(st.integers(0, 15), min_size=n, max_size=n))
    k = draw(st.one_of(st.integers(0, 15), st.sampled_from([0, 1, 15])))
    return f"{nums}\n{k}"

def validate(inp):
    import json
    lines = inp.split("\n")
    if len(lines) != 2:
        return False
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    if not isinstance(nums, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    if not (1 <= len(nums) <= 10**5):
        return False
    if not all(isinstance(v, int) and not isinstance(v, bool) and 0 <= v <= 10**6 for v in nums):
        return False
    if not (0 <= k <= 10**6):
        return False
    return True

def ref(inp):
    import json
    lines = inp.split("\n")
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    # XOR of the whole array in its current state
    x = 0
    for v in nums:
        x ^= v
    # Each operation flips one bit of one element, which toggles exactly one bit
    # of the total XOR (any bit position is available, including leading zeros).
    # Bits above position 21 are never needed since all values are < 2^21.
    # So the minimum number of operations is the number of bit positions where
    # x and k differ.
    d = x ^ k
    count = 0
    for b in range(22):
        if (d >> b) & 1:
            count += 1
    return json.dumps(count)
